-- Large Article Sentinel local seed
-- Import with:
-- docker exec -i article-sentinel-mysql mysql -uroot -p'Holmes64125135' article_sentinel < scripts/article_inspection_seed_large.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Minimal runtime-compatible article tables for local testing.
CREATE TABLE IF NOT EXISTS `xt_article` (
  `id` BIGINT UNSIGNED NOT NULL,
  `orgid` BIGINT UNSIGNED NOT NULL,
  `title` VARCHAR(255) NOT NULL DEFAULT '',
  `short_title` VARCHAR(255) NOT NULL DEFAULT '',
  `rich_title` TEXT NULL,
  `keyword` VARCHAR(255) NOT NULL DEFAULT '',
  `desc` TEXT NULL,
  `state` TINYINT NOT NULL DEFAULT 0,
  `publish_at_time` DATETIME NULL,
  `update_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_org_state_id` (`orgid`, `state`, `id`),
  KEY `idx_org_publish` (`orgid`, `publish_at_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `xt_article_info` (
  `article_id` BIGINT UNSIGNED NOT NULL,
  `body` LONGTEXT NULL,
  `update_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`article_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Clean only the large-seed ranges.
DELETE FROM `xt_article_inspect_field_change_logs` WHERE `id` BETWEEN 9700001 AND 9799999;
DELETE FROM `xt_article_inspect_operation_logs` WHERE `id` BETWEEN 9600001 AND 9699999;
DELETE FROM `xt_article_inspect_actions` WHERE `id` BETWEEN 9500001 AND 9599999;
DELETE FROM `xt_article_inspect_result_hits` WHERE `id` BETWEEN 9400001 AND 9499999;
DELETE FROM `xt_article_inspect_results` WHERE `id` BETWEEN 9300001 AND 9399999;
DELETE FROM `xt_article_inspect_task_keywords` WHERE `task_id` BETWEEN 9202001 AND 9299999;
DELETE FROM `xt_article_inspect_tasks` WHERE `id` BETWEEN 9202001 AND 9299999;
DELETE FROM `xt_article_inspect_keyword_scopes` WHERE `keyword_id` BETWEEN 9101001 AND 9199999;
DELETE FROM `xt_article_inspect_keywords` WHERE `id` BETWEEN 9101001 AND 9199999;
DELETE FROM `xt_article_info` WHERE `article_id` BETWEEN 9100001 AND 9100048;
DELETE FROM `xt_article` WHERE `id` BETWEEN 9100001 AND 9100048;












SET FOREIGN_KEY_CHECKS = 1;
